<x-layouts::app :title="__($task->exists ? 'Edit task' : 'New task')"><div class="mx-auto max-w-3xl p-4 md:p-8"><h1 class="mb-5 text-2xl font-semibold">{{ $task->exists ? 'Edit task' : 'Create task' }}</h1><form method="POST" action="{{ $task->exists ? route('tasks.update',$task) : route('tasks.store') }}" class="grid gap-4 rounded-xl border p-5">@csrf @if($task->exists)@method('PUT')@endif @foreach($errors->all() as $error)<p class="text-sm text-red-600">{{ $error }}</p>@endforeach<label>Title<input required name="title" value="{{ old('title',$task->title) }}" class="mt-1 w-full rounded-lg border bg-transparent p-2"></label><label>Description<textarea name="description" class="mt-1 w-full rounded-lg border bg-transparent p-2">{{ old('description',$task->description) }}</textarea></label><label>Employee<select required name="assigned_to" class="mt-1 w-full rounded-lg border bg-transparent p-2">@foreach($employees as $employee)<option value="{{ $employee->id }}" @selected(old('assigned_to',$task->assigned_to)==$employee->id)>{{ $employee->name }}</option>@endforeach</select></label><div class="grid gap-3 sm:grid-cols-2"><label>Priority<select name="priority" class="mt-1 w-full rounded-lg border bg-transparent p-2">@foreach(['Low','Medium','High','Urgent'] as $option)<option @selected(old('priority',$task->priority)===$option)>{{ $option }}</option>@endforeach</select></label><label>Status<select name="status" class="mt-1 w-full rounded-lg border bg-transparent p-2">@foreach(['To Do','In Progress','Completed','Blocked'] as $option)<option @selected(old('status',$task->status)===$option)>{{ $option }}</option>@endforeach</select></label></div><div class="grid gap-3 sm:grid-cols-2"><label>Start date<input type="date" name="start_date" value="{{ old('start_date',$task->start_date?->format('Y-m-d')) }}" class="mt-1 w-full rounded-lg border bg-transparent p-2"></label><label>Due date<input type="date" name="due_date" value="{{ old('due_date',$task->due_date?->format('Y-m-d')) }}" class="mt-1 w-full rounded-lg border bg-transparent p-2"></label></div><button class="rounded-lg bg-blue-600 px-4 py-2 text-white">Save task</button></form></div></x-layouts::app>
